public static void main(String[] args){
  var parser=new OptionParser();
  var helpOpt=parser.accepts("help","Print this help text").forHelp();
  var hostOpt=parser.accepts("host","Bisq node hostname or IP").withRequiredArg().defaultsTo("localhost");
  var portOpt=parser.accepts("port","Bisq node rpc port").withRequiredArg().ofType(Integer.class).defaultsTo(9998);
  var passwordOpt=parser.accepts("password","Bisq node rpc server password").withRequiredArg();
  try {
    var options=parser.parse(args);
    if (options.has(helpOpt)) {
      printHelp(parser,out);
      exit(EXIT_SUCCESS);
    }
    @SuppressWarnings("unchecked") var nonOptionArgs=(List<String>)options.nonOptionArguments();
    if (nonOptionArgs.isEmpty()) {
      printHelp(parser,err);
      err.println("Error: no command specified");
      exit(EXIT_FAILURE);
    }
    var host=options.valueOf(hostOpt);
    var port=options.valueOf(portOpt);
    var password=options.valueOf(passwordOpt);
    if (password == null) {
      err.println("Error: no password specified");
      exit(EXIT_FAILURE);
    }
    try {
      var channel=ManagedChannelBuilder.forAddress(host,port).usePlaintext().build();
      var credentials=new AuthHeaderCallCredentials(password);
      var command=nonOptionArgs.get(0);
      if ("getversion".equals(command)) {
        var stub=GetVersionGrpc.newBlockingStub(channel).withCallCredentials(credentials);
        var request=GetVersionRequest.newBuilder().build();
        var version=stub.getVersion(request).getVersion();
        out.println(version);
        shutdown(channel);
        exit(EXIT_SUCCESS);
      }
      if ("getbalance".equals(command)) {
        var stub=GetBalanceGrpc.newBlockingStub(channel).withCallCredentials(credentials);
        var request=GetBalanceRequest.newBuilder().build();
        var balance=stub.getBalance(request).getBalance();
        if (balance == -1) {
          err.println("Error: server is still initializing");
          shutdown(channel);
          exit(EXIT_FAILURE);
        }
        out.println(formatBalance(balance));
        shutdown(channel);
        exit(EXIT_SUCCESS);
      }
      err.printf("Error: unknown command '%s'\n",command);
    } catch (IllegalArgumentException e) {
      err.println("Error: invalid host or port specified");
      exit(EXIT_FAILURE);
    }
  } catch (  OptionException ex) {
    err.println("Error: " + ex.getMessage());
  }
  catch (  StatusRuntimeException ex) {
    Throwable t=ex.getCause() == null ? ex : ex.getCause();
    err.println("Error: " + t.getMessage());
  }
  finally {
    exit(EXIT_FAILURE);
  }
}
